/// `dir`, with the name it shows as in the breadcrumb.
pub fn crumbs(dir: &Path) -> Vec<(String, PathBuf)> {
    dir.ancestors()
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .map(|path| {
            let name = path
                .file_name()
                .map(|name| name.to_string_lossy().into_owned())
                .unwrap_or_else(|| path.display().to_string());
            (name, path.to_path_buf())
